={{ {
  "model": "OLLAMA_LOCAL_MODEL",
  "messages": [
    { "role": "system", "content": "You check whether the Wikipedia background context is usable as GENERAL BACKGROUND ONLY for a pet care wellness article - never as a source for medical claims, product specs, or commercial facts; it must never be cited as evidence. Decide if the keyword is a legitimate on-topic subject for its silo (block harm, cure-claims, or topics that cannot be written without unsupported medical claims) and propose 3-5 article sections with headings and one-line writing prompts. List the load-bearing factual/health claims so evidence tags exist before writing. Respond ONLY as JSON: {\"relevant\": true/false, \"sections\": [{\"heading\": \"...\", \"prompt\": \"...\"}]}" },
    { "role": "user", "content": "Keyword to target: " + $node['Form Trigger - Topic Input'].json['Keyword (long-tail, SEO target)'] + "\nWikipedia topic: " + $node['Form Trigger - Topic Input'].json['Wikipedia Topic (clean subject, e.g. Glucosamine)'] + "\nWikipedia summary: " + $json.extract }
  ]
} }}

={{ {
  "model": "OPENROUTER_MODEL_FOR_WRITING",
  "messages": [
    { "role": "system", "content": "You write one section of a TailWell pet care article. Tone: warm, credible, editorial. Never invent facts, statistics, medical claims, product specs, prices, or URLs - only content grounded in the supplied evidence. NEVER write a real product name, price, or URL. Where a product recommendation naturally belongs, insert exactly this placeholder tag with a category matching one of: joint-supplement, fresh-food, cbd-wellness, insurance, gear-tracker, gear-feeder, dental, odor-control - example: [tw_product_placeholder category=\"joint-supplement\"]. Tag every health/safety/nutrition/statistical sentence with its evidence id inline, exactly like [ev:TWP-EVID-0000], using only evidence ids given to you; never tag Wikipedia. Health-adjacent advice must include \"talk to your veterinarian\" framing and never read as a diagnosis, cure, or treatment directive. Output plain HTML for the section only: h2 heading, short paragraphs, lists where useful. No preamble, no markdown fences." },
    { "role": "user", "content": "Section heading: " + $json.heading + "\nWriting prompt: " + $json.prompt }
  ]
} }}

parameters.jsCode:
const text = String($json.body ?? $json.data ?? $json).replace(/^\uFEFF/, '');
const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const header = lines.shift().split(',').map(h => h.trim());
const rows = [];
for (const line of lines) {
  const cells = [];
  let cur = '', q = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (q) {
      if (c === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; }
      else cur += c;
    } else if (c === '"') q = true;
    else if (c === ',') { cells.push(cur); cur = ''; }
    else cur += c;
  }
  cells.push(cur);
  const row = {};
  header.forEach((h, i) => row[h] = (cells[i] ?? '').trim());
  rows.push(row);
}
const products = rows.filter(p => p.status === 'approved' && String(p.enabled).toLowerCase() === 'true');
return [{ json: { products, parsed_count: products.length, total_rows: rows.length } }];

const merged = $node['Merge - Products + Sections'].json;
const articleHtml = merged.section_html.join('\n\n');
const products = merged.products || [];
const silo = $node['Form Trigger - Topic Input'].json['Silo'];
const home = String($env.WORDPRESS_URL || '').replace(/\/+$/, '');

const placeholderRegex = /\[tw_product_placeholder category="([a-z-]+)"\]/g;
let unmatched = [];

const finalHtml = articleHtml.replace(placeholderRegex, (match, category) => {
  const approved = products.filter(p => p.category === category && p.status === 'approved');
  if (approved.length === 0) {
    unmatched.push(category);
    return '<!-- NO APPROVED PRODUCT FOUND for category: ' + category + ' - manual fill required before publish -->';
  }
  const p = approved[0];
  const safe = (s) => String(s).replace(/"/g, '&quot;');
  return '[tw_product name="' + safe(p.name) + '" why="' + safe(p.why) + '" price="' + safe(p.price) + '" url="' + safe(p.url) + '" brand="' + safe(p.brand || '') + '" image="' + safe(p.image_url || '') + '" category="' + safe(p.category || '') + '" partner="' + safe(p.affiliate_partner || '') + '" vet="' + safe(p.vet_verified || '') + '"]';
});

const siloLink = home ? home + '/category/' + silo + '/' : '/category/' + silo + '/';
const internalBlock = '<hr class="tw-internal-sep"><p class="tw-internal-links"><a href="' + siloLink + '">More ' + silo.replace(/-/g, ' ') + ' guides</a> &middot; <a href="' + (home || '/') + '">Browse all of TailWell</a></p>';

return [{ json: { final_html: finalHtml + internalBlock, unmatched_categories: unmatched, has_unmatched: unmatched.length > 0, internal_links: 2 } }];

