={{ {
  "model": "OPENROUTER_MODEL_FOR_QA",
  "messages": [
    { "role": "system", "content": "You are a strict fact-check and QA reviewer for a pet care wellness blog. Apply this rubric and FAIL on any breach: 1) No unsupported medical/health claims - every health/safety/nutrition/statistical sentence must carry an [ev:TWP-EVID-####] tag backed by real evidence (tier >= s2 for health claims; s3 manufacturer evidence may support product specs only); no invented statistics or product specs; Wikipedia is never evidence. 2) Every product mention must come from a [tw_product] shortcode with real attributes - any leftover [tw_product_placeholder] or NO APPROVED PRODUCT comment is an automatic FAIL. 3) No duplicate/plagiarized content. 4) Vet-consultation framing present for any health-adjacent advice. 5) Affiliate links, if present, carry rel=\"noopener nofollow sponsored\". 6) The article must end with the \"More {silo} guides\" and \"Browse all of TailWell\" internal links (the tw-internal-links block). Respond ONLY with JSON: {\"result\": \"PASS\" or \"FAIL\", \"reasons\": [ ... ]}" },
    { "role": "user", "content": $json.final_html }
  ]
} }}

={{ {
  "model": "OPENROUTER_MODEL_FOR_WRITING",
