    { "role": "user", "content": "Target keyword: " + $node['Form Trigger - Topic Input'].json['Keyword (long-tail, SEO target)'] + "\n\nArticle: " + $node['Insert Real Affiliate Products'].json.final_html }
  ]
} }}

